class Calculator:
    def __init__(self, expression):
        self.expression = expression.replace(' ', '')
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def parse_number(self):
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_parentheses(self):
        self.advance()  # skip '('
        result = self.expr()
        self.advance()  # skip ')'
        return result

    def factor(self):
        if self.current_char == '(':
            return self.parse_parentheses()
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()
        self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()
            if operation == '*':
                result *= self.factor()
            elif operation == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()
            if operation == '+':
                result += self.term()
            elif operation == '-':
                result -= self.term()
        return result

